-- Additional original method notes motivated by the imported problem statements.
update public.lesson_blocks set position=5 where kind='key_facts' and lesson_id in
(select id from public.lessons where attribution='Авторский конспект OlympAI'
 or id in ('algebra-roots-and-coefficients','combinatorics-counting','number-theory-divisibility',
 'mechanics-connected-bodies','electrodynamics-resistance','thermodynamics-first-law'));
insert into public.lesson_blocks(lesson_id,kind,heading,body,position)
select lesson_id,'explanation',heading,body,4
from jsonb_to_recordset($methods$[
  {
    "lesson_id": "algebra-roots-and-coefficients",
    "heading": "Функциональное уравнение — область определения решает многое",
    "body": "Пусть \\(f\\colon\\mathbb Z\\to\\mathbb R\\), \\(f(x+y)=f(x)+f(y)\\), \\(f(1)=2\\). Подстановка нулей даёт \\(f(0)=0\\), а \\(y=-x\\) даёт \\(f(-x)=-f(x)\\). По индукции для положительных целых \\(n\\) получаем \\(f(n)=2n\\), затем то же для отрицательных. Проверка подстановкой завершает решение.\n\nНа всех действительных числах из одной аддитивности линейность без дополнительных условий уже не следует. Не переносите доказательство для целых аргументов на действительные."
  },
  {
    "lesson_id": "combinatorics-counting",
    "heading": "Рекуррентный подсчёт — запрет соседних единиц",
    "body": "Пусть \\(a_n\\) — число двоичных строк длины \\(n\\) без соседних единиц. Строка оканчивается либо нулём, тогда перед ним любая допустимая строка длины \\(n-1\\), либо единицей. Во втором случае предыдущий символ обязательно ноль и остаётся строка длины \\(n-2\\). Случаи не пересекаются, поэтому\n\n\\[a_n=a_{n-1}+a_{n-2},\\qquad a_0=1,\\quad a_1=2.\\]\n\nПолучаем \\(a_2=3,\\ a_3=5,\\ a_4=8,\\ a_5=13\\). Для более сложного запрета состоянием служит не только длина, но и последние несколько символов."
  },
  {
    "lesson_id": "number-theory-divisibility",
    "heading": "Порядок числа по модулю",
    "body": "Если \\(\\gcd(a,m)=1\\), порядок \\(\\operatorname{ord}_m(a)\\) — наименьшее положительное \\(d\\), при котором \\(a^d\\equiv1\\pmod m\\). Если \\(a^n\\equiv1\\pmod m\\), разделим \\(n=qd+r\\) с \\(0\\le r<d\\). Получаем \\(a^r\\equiv1\\), откуда минимальность даёт \\(r=0\\). Значит, \\(d\\mid n\\).\n\nНапример, \\(2,4,1\\) — первые степени двойки по модулю 7. Поэтому \\(7\\mid(2^n-1)\\) тогда и только тогда, когда \\(3\\mid n\\)."
  },
  {
    "lesson_id": "geometry-olympiad-methods",
    "heading": "Чева — как доказывать пересечение трёх прямых",
    "body": "В треугольнике \\(ABC\\) точки \\(D,E,F\\) лежат внутри сторон \\(BC,CA,AB\\). Прямые \\(AD,BE,CF\\) проходят через одну точку тогда и только тогда, когда\n\n\\[\\frac{BD}{DC}\\cdot\\frac{CE}{EA}\\cdot\\frac{AF}{FB}=1.\\]\n\nОтношения можно получить из площадей треугольников с общей высотой. Например, если первые два отношения равны \\(2\\) и \\(3\\), для пересечения требуется \\(AF/FB=1/6\\). Для точек на продолжениях используйте направленную версию с согласованными знаками. Не смешивайте её с теоремой Менелая о коллинеарности."
  },
  {
    "lesson_id": "mechanics-connected-bodies",
    "heading": "Качение — почему нельзя забыть вращение",
    "body": "Тело массы \\(m\\), радиуса \\(R\\) и момента инерции \\(I\\) катится без скольжения по наклонной плоскости угла \\(\\alpha\\). Вдоль плоскости \\(mg\\sin\\alpha-f=ma\\), а момент силы трения даёт \\(fR=I(a/R)\\). Исключая трение, получаем\n\n\\[a=\\frac{g\\sin\\alpha}{1+I/(mR^2)}.\\]\n\nДля однородного сплошного цилиндра \\(I=mR^2/2\\), поэтому \\(a=2g\\sin\\alpha/3\\). После расчёта проверьте, что нужное трение не превосходит предельное трение покоя. Иначе предположение о чистом качении неверно."
  },
  {
    "lesson_id": "electrodynamics-resistance",
    "heading": "Метод изображений — границы применимости",
    "body": "Для точечного заряда \\(q\\) на высоте \\(h\\) над бесконечной заземлённой проводящей плоскостью поле над ней совпадает с полем заряда и его изображения \\(-q\\) на глубине \\(h\\). На плоскости суммарный потенциал нулевой. Расстояние между зарядом и изображением равно \\(2h\\), поэтому модуль силы притяжения\n\n\\[F=\\frac{1}{4\\pi\\varepsilon_0}\\frac{q^2}{(2h)^2}.\\]\n\nИзображение — вычислительный приём, а не второй реальный заряд. Для незаземлённого проводника или другой формы поверхности граничные условия изменяются и эта конструкция может не работать."
  },
  {
    "lesson_id": "thermodynamics-first-law",
    "heading": "Влажность — давление пара и насыщение",
    "body": "Относительная влажность \\(\\varphi\\) задаётся отношением парциального давления пара к давлению насыщения при той же температуре\n\n\\[\\varphi=\\frac{p_v}{p_{\\rm нас}(T)}.\\]\n\nПри изохорном нагревании без испарения и конденсации число молекул пара постоянно, поэтому \\(p_v\\propto T\\). Но \\(p_{\\rm нас}(T)\\) меняется по другой зависимости, так что влажность нельзя считать постоянной. Если расчёт даёт \\(\\varphi>1\\) при охлаждении с возможностью конденсации, часть пара сконденсируется. Массу оставшегося пара находят из \\(p_vV=(m_v/M)RT\\)."
  },
  {
    "lesson_id": "optics-rays-and-lenses",
    "heading": "Протяжённый предмет — увеличение не везде одинаково",
    "body": "Если предмет наклонён к главной оптической оси, разные точки имеют разные расстояния \\(a\\). Для каждой точки тонкая собирающая линза даёт\n\n\\[b=\\frac{fa}{a-f},\\qquad y_{\\rm im}=-\\frac ba\\,y.\\]\n\nПоэтому нельзя умножить всю площадь наклонённой фигуры на один коэффициент увеличения. Отобразите её вершины и выясните геометрию изображения. Для предмета в плоскости, перпендикулярной оси, все точки имеют одинаковое \\(a\\), и тогда площади действительно относятся как \\(\\Gamma^2\\)."
  },
  {
    "lesson_id": "waves-oscillations",
    "heading": "Плавающее тело как осциллятор",
    "body": "Пусть тело плавает вертикально, площадь его сечения у уровня жидкости равна \\(S\\), плотность жидкости \\(\\rho\\). При малом дополнительном погружении \\(x\\) вытесненный объём увеличивается приблизительно на \\(Sx\\). Дополнительная сила Архимеда направлена вверх и равна \\(\\rho gSx\\). Поэтому эффективная жёсткость \\(k_{\\rm эф}=\\rho gS\\), а\n\n\\[T=2\\pi\\sqrt{\\frac{m}{\\rho gS}}.\\]\n\nМодель предполагает малые смещения, отсутствие заметного сопротивления и пренебрежимо малую присоединённую массу жидкости. У тела переменного сечения \\(S\\) берут именно в равновесном положении."
  },
  {
    "lesson_id": "modern-physics-photons",
    "heading": "Зачем в реакциях проверять импульс",
    "body": "Один фотон не может превратиться в пару электрон–позитрон в пустом пространстве. Если бы пара возникла, в её системе центра импульса суммарный импульс был бы нулевым. Но фотон имеет ненулевой импульс \\(p=E/c\\) в любой инерциальной системе и ненулевую энергию. Одновременно сохранить энергию и импульс не удаётся.\n\nРядом с ядром процесс возможен, поскольку ядро принимает часть импульса. Оценка энергии только через \\(2m_ec^2\\) задаёт необходимый энергетический масштаб, но точный порог требует учёта отдачи."
  }
]$methods$::jsonb)
as m(lesson_id text,heading text,body text);
